package com.example.k234112e_hqv;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.ImageView;
import android.widget.ListView;
import android.widget.Spinner;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.example.adapters.EmployeeAdapter;
import com.example.models.Department;
import com.example.models.Employee;

import java.util.ArrayList;

public class EmployeeAdvanceManagementActivity extends AppCompatActivity {
    ListView lvEmployee;
    ArrayList<Employee>listOfEmployee;
    EmployeeAdapter adapterEmployee;
    Spinner spDepartment;
    ArrayList<Department> lisOfDepartment;
    ArrayAdapter<Department> adapterDepartment;
    ImageView img_add_emp,img_edit_emp,img_delete_img;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_employee_advance_management);
        addViews();
        sampleData();
        addEvent();
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
    }

    private void addEvent() {
        spDepartment.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> adapterView, View view, int i, long l) {
                adapterEmployee.clear();
                if (i == 0) {
                    // Hiển thị toàn bộ nhân viên từ tất cả các phòng ban
                    for (int j = 1; j < lisOfDepartment.size(); j++) {
                        adapterEmployee.addAll(lisOfDepartment.get(j).getListOfEmployee());
                    }
                } else {
                    // Hiển thị nhân viên của phòng ban được chọn
                    Department selectedDepartment = lisOfDepartment.get(i);
                    adapterEmployee.addAll(selectedDepartment.getListOfEmployee());
                }
                adapterEmployee.notifyDataSetChanged();
            }

            @Override
            public void onNothingSelected(AdapterView<?> adapterView) {
            }
        });

        img_add_emp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Intent intent = new Intent(EmployeeAdvanceManagementActivity.this, AddEmployeeActivity.class);
                startActivityForResult(intent, 999);
            }
        });
    }


    private void sampleData() {

        Department d0=new Department("D000","-----All-----");
        Department d1=new Department("D001","HR");
        Department d2=new Department("D002","IT");
        Department d3=new Department("D003","Finance");
        Department d4=new Department("D004","SCM");

        lisOfDepartment.add(d0);
        lisOfDepartment.add(d1);
        lisOfDepartment.add(d2);
        lisOfDepartment.add(d3);
        lisOfDepartment.add(d4);
        adapterDepartment.notifyDataSetChanged();

        d1.addEmployee(new Employee("E001","John Doe","123456789"));
        d1.addEmployee(new Employee("E002","Jane Smith","987654321"));
        d2.addEmployee(new Employee("E003","Alice Johnson","555555555"));
        d2.addEmployee(new Employee("E004","Quoc Viet","0123456789"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));

        ArrayList<Employee> lisOfEmp4=new ArrayList<>();
        lisOfEmp4.add(new Employee("E001","John Doe","123456789"));
        lisOfEmp4.add(new Employee("E002","Jane Smith","987654321"));
        lisOfEmp4.add(new Employee("E003","Alice Johnson","555555555"));
        lisOfEmp4.add(new Employee("E004","Quoc Viet","012345678"));
        d4.addListEmployee(lisOfEmp4);


    }

    private void addViews(){
        lvEmployee=findViewById(R.id.lvEmployee);
        listOfEmployee=new ArrayList<>();
        adapterEmployee=new EmployeeAdapter(this,R.layout.item_custome_employee);
        listOfEmployee.add(new Employee("E001","John Doe","123456789"));
        listOfEmployee.add(new Employee("E002","Jane Smith","987654321"));
        listOfEmployee.add(new Employee("E003","Alice Johnson","555555555"));
        listOfEmployee.add(new Employee("E004","Quoc Viet","0123456789"));
        listOfEmployee.add(new Employee("E005","Quoc Sang","0987654321"));
        adapterEmployee.addAll(listOfEmployee);
        lvEmployee.setAdapter(adapterEmployee);
        adapterEmployee.notifyDataSetChanged();

        spDepartment=findViewById(R.id.spDepartment);
        lisOfDepartment=new ArrayList<>();
        adapterDepartment=new ArrayAdapter<>(this,
                android.R.layout.simple_spinner_item,lisOfDepartment);
        adapterDepartment.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spDepartment.setAdapter(adapterDepartment);
    }
}

package com.example.k234112e_hqv;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.ImageView;
import android.widget.ListView;
import android.widget.Spinner;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.example.adapters.EmployeeAdapter;
import com.example.models.Department;
import com.example.models.Employee;

import java.util.ArrayList;

public class EmployeeAdvanceManagementActivity extends AppCompatActivity {
    ListView lvEmployee;
    ArrayList<Employee>listOfEmployee;
    EmployeeAdapter adapterEmployee;
    Spinner spDepartment;
    ArrayList<Department> lisOfDepartment;
    ArrayAdapter<Department> adapterDepartment;
    ImageView img_add_emp,img_edit_emp,img_delete_img;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_employee_advance_management);
        addViews();
        sampleData();
        addEvent();
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == 999 && resultCode == 888 && data != null) {
            Employee emp = (Employee) data.getSerializableExtra("New_Employee");
            if (emp == null) {
                return;
            }
            int selectedIndex = spDepartment.getSelectedItemPosition();
            if (selectedIndex <= 0 && lisOfDepartment.size() > 1) {
                selectedIndex = 1;
            }
            if (selectedIndex > 0 && selectedIndex < lisOfDepartment.size()) {
                lisOfDepartment.get(selectedIndex).addEmployee(emp);
            }
            refreshEmployeesForDepartment(spDepartment.getSelectedItemPosition());
        }
    }

    private void addEvent() {
        spDepartment.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> adapterView, View view, int i, long l) {
                refreshEmployeesForDepartment(i);
            }

            @Override
            public void onNothingSelected(AdapterView<?> adapterView) {
            }
        });

        img_add_emp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Intent intent = new Intent(EmployeeAdvanceManagementActivity.this, AddEmployeeActivity.class);
                startActivityForResult(intent, 999);
            }
        });
    }

    private void refreshEmployeesForDepartment(int index) {
        adapterEmployee.clear();
        if (index == 0) {
            for (int j = 1; j < lisOfDepartment.size(); j++) {
                adapterEmployee.addAll(lisOfDepartment.get(j).getListOfEmployee());
            }
        } else if (index > 0 && index < lisOfDepartment.size()) {
            adapterEmployee.addAll(lisOfDepartment.get(index).getListOfEmployee());
        }
        adapterEmployee.notifyDataSetChanged();
    }

    private void sampleData() {

        Department d0=new Department("D000","-----All-----");
        Department d1=new Department("D001","HR");
        Department d2=new Department("D002","IT");
        Department d3=new Department("D003","Finance");
        Department d4=new Department("D004","SCM");

        lisOfDepartment.add(d0);
        lisOfDepartment.add(d1);
        lisOfDepartment.add(d2);
        lisOfDepartment.add(d3);
        lisOfDepartment.add(d4);
        adapterDepartment.notifyDataSetChanged();

        d1.addEmployee(new Employee("E001","John Doe","123456789"));
        d1.addEmployee(new Employee("E002","Jane Smith","987654321"));
        d2.addEmployee(new Employee("E003","Alice Johnson","555555555"));
        d2.addEmployee(new Employee("E004","Quoc Viet","0123456789"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));
        d3.addEmployee(new Employee("E005","Quoc Sang","0987654321"));

        ArrayList<Employee> lisOfEmp4=new ArrayList<>();
        lisOfEmp4.add(new Employee("E001","John Doe","123456789"));
        lisOfEmp4.add(new Employee("E002","Jane Smith","987654321"));
        lisOfEmp4.add(new Employee("E003","Alice Johnson","555555555"));
        lisOfEmp4.add(new Employee("E004","Quoc Viet","012345678"));
        d4.addListEmployee(lisOfEmp4);


    }

    private void addViews(){
        lvEmployee=findViewById(R.id.lvEmployee);
        listOfEmployee=new ArrayList<>();
        adapterEmployee=new EmployeeAdapter(this,R.layout.item_custome_employee);
        listOfEmployee.add(new Employee("E001","John Doe","123456789"));
        listOfEmployee.add(new Employee("E002","Jane Smith","987654321"));
        listOfEmployee.add(new Employee("E003","Alice Johnson","555555555"));
        listOfEmployee.add(new Employee("E004","Quoc Viet","0123456789"));
        listOfEmployee.add(new Employee("E005","Quoc Sang","0987654321"));
        adapterEmployee.addAll(listOfEmployee);
        lvEmployee.setAdapter(adapterEmployee);
        adapterEmployee.notifyDataSetChanged();

        spDepartment=findViewById(R.id.spDepartment);
        lisOfDepartment=new ArrayList<>();
        adapterDepartment=new ArrayAdapter<>(this,
                android.R.layout.simple_spinner_item,lisOfDepartment);
        adapterDepartment.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spDepartment.setAdapter(adapterDepartment);

        img_add_emp = findViewById(R.id.img_add_emp);
        img_edit_emp = findViewById(R.id.img_edit_emp);
        img_delete_img = findViewById(R.id.img_delete_img);
    }
}

package com.example.k234112e_hqv;

import android.app.Dialog;
import android.content.DialogInterface;
import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.ListView;



import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.app.AlertDialog;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;


import java.util.ArrayList;

public class EmployeeManagementActivity extends AppCompatActivity {

    Button btnExit;
    ListView lvData;
    ArrayList<String> listEmployee;
    ArrayAdapter<String> adapterEmployee;
    EditText edtid, edtname, edtphone;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_employee_management);
        addViews();
        addEvents();
        loadData();
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
    }

    private void addEvents() {
        btnExit.setOnClickListener(view -> processExit());
        lvData.setOnItemClickListener((adapterView, view, position, id) -> displayEmployee(position));
    }

    private void displayEmployee(int i) {
        String data = listEmployee.get(i);
        String[] parts = data.split("-");
        if (parts.length > 0) {
            edtid.setText(parts[0]);
        }
        if (parts.length > 1) {
            edtname.setText(parts[1]);
        }
        if (parts.length > 2) {
            edtphone.setText(parts[2]);
        }
    }

    private void loadData() {
        listEmployee.add("e1-Viet-0987563735");
        listEmployee.add("e2-Hoa-0647485858");
        listEmployee.add("e3-Ngan-0364849959");
        listEmployee.add("e4-Duc-0374844485");
        listEmployee.add("e5-Cam-0374859578");
        adapterEmployee.notifyDataSetChanged();
    }

    private void processExit() {
        Dialog custome = new Dialog(this);
        custome.setContentView(R.layout.custom_dialog);
        ImageView imgSave = custome.findViewById(R.id.imgYes);
        ImageView imgCancel = custome.findViewById(R.id.imgCancel);
        imgSave.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                finish();
            }
        });
        imgCancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                custome.dismiss();
            }
        });
        custome.show();
    }

    private void addViews() {
        btnExit = findViewById(R.id.btnExit);
        lvData = findViewById(R.id.lvData);
        listEmployee = new ArrayList<>();
        adapterEmployee = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, listEmployee);
        lvData.setAdapter(adapterEmployee);
        edtid = findViewById(R.id.edtid);
        edtname = findViewById(R.id.edtname);
        edtphone = findViewById(R.id.edtphone);
    }

    public void processSave(View view) {
        String id = edtid.getText().toString().trim();
        String name = edtname.getText().toString().trim();
        String phone = edtphone.getText().toString().trim();
        if (id.isEmpty() || name.isEmpty() || phone.isEmpty()) {
            return;
        }
        String record = id + "-" + name + "-" + phone;
        int index = findEmployeeIndexById(id);
        if (index == -1) {
            listEmployee.add(record);
        } else {
            listEmployee.set(index, record);
        }
        adapterEmployee.notifyDataSetChanged();
    }

    private int findEmployeeIndexById(String id) {
        for (int i = 0; i < listEmployee.size(); i++) {
            String data = listEmployee.get(i);
            String[] parts = data.split("-");
            if (parts.length > 0 && parts[0].equalsIgnoreCase(id)) {
                return i;
            }
        }
        return -1;
    }

    public void processDelete(View view) {
        String id = edtid.getText().toString().trim();
        if (id.isEmpty()) {
            Toast.makeText(this, "Can chon nhan vien de xoa", Toast.LENGTH_SHORT).show();
            return;
        }
        int index = findEmployeeIndexById(id);
        if (index == -1) {
            Toast.makeText(this, "Khong tim thay nhan vien", Toast.LENGTH_SHORT).show();
            return;
        }
        AlertDialog.Builder builder = new AlertDialog.Builder(this);
        builder.setTitle("Confirm delete");
        builder.setMessage("Ban co muon xoa nhan vien nay?");
        builder.setPositiveButton("Co", new DialogInterface.OnClickListener() {
            @Override
            public void onClick(DialogInterface dialogInterface, int i) {
                listEmployee.remove(index);
                adapterEmployee.notifyDataSetChanged();
                edtid.setText("");
                edtname.setText("");
                edtphone.setText("");
            }
        });
        builder.setNegativeButton("Khong", null);
        builder.show();
    }
}

package com.example.k234112e_hqv;

import android.app.Dialog;
import android.content.DialogInterface;
import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
